using FluentValidation;namespace Namaa.Application.Invoices.Commands.AddInvoiceItem;public sealed class AddInvoiceItemCommandValidator:AbstractValidator<AddInvoiceItemCommand>{public AddInvoiceItemCommandValidator(){RuleFor(x=>x.InvoiceId).GreaterThan(0);RuleFor(x=>x.Description).NotEmpty().MaximumLength(500);RuleFor(x=>x.Quantity).GreaterThan(0);RuleFor(x=>x.UnitPrice).GreaterThanOrEqualTo(0);RuleFor(x=>x.DiscountAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.TaxAmount).GreaterThanOrEqualTo(0);}}
